//! A handle to a local variable in generated JVM bytecode.
//!
//! Port of `ghidra.pcode.emu.jit.gen.util.Local`.
//!
//! The JVM `<t>load` and `<t>store` instructions take an index argument. This type wraps an index
//! in a named handle to avoid tracking indices manually. Instances are generated by scope methods
//! like [`Scope::decl`], [`Def::param`], and [`Def::done`].

use crate::pcode::emu::jit::gen::util::types::BNonVoid;
use crate::pcode::seam_stubs::{Emitter, Label};

/// A handle to a local variable in generated JVM bytecode.
///
/// Port of `ghidra.pcode.emu.jit.gen.util.Local<T>`. Wraps a JVM local variable index
/// together with its type, name, and scope information. `T` is the machine type of the variable.
///
/// # Type Parameter
///
/// - `T`: The type of the variable, implementing [`BNonVoid`]. Typically a concrete type like
///   [`TInt`](crate::pcode::emu::jit::gen::util::types::TInt) or
///   [`TRef`](crate::pcode::emu::jit::gen::util::types::TRef).
#[derive(Debug, Clone)]
pub struct Local<T: BNonVoid> {
    /// The (machine) type of the variable.
    pub type_: T,
    /// The name of the variable.
    pub name: String,
    /// The local variable index in the JVM method.
    pub index: i32,
}

impl<T: BNonVoid> Local<T> {
    /// Construct a local variable handle.
    ///
    /// Port of `Local.of(T, String, int)`. Direct use is not recommended; instances are
    /// typically generated by scope methods instead.
    ///
    /// # Arguments
    ///
    /// - `type_`: The type of the variable.
    /// - `name`: The name of the variable.
    /// - `index`: The local variable index.
    pub fn of(type_: T, name: impl Into<String>, index: i32) -> Self {
        Self { type_, name: name.into(), index }
    }
}

/// Declare this local variable in the method being generated.
///
/// Port of `Local.decl(Emitter, Local, Lbl, Lbl)`. Records the local variable in the
/// emitter's method visitor, specifying its name, type descriptor, scope (from `start` to
/// `end` labels), and index.
///
/// # Arguments
///
/// - `em`: The emitter (and wrapped ASM `MethodVisitor`) into which to record the declaration.
/// - `local`: The local variable handle.
/// - `start`: The label marking the start of the variable's scope.
/// - `end`: The label marking the end of the variable's scope.
///
/// # Returns
///
/// The same emitter, for method chaining.
pub fn decl<N, T: BNonVoid>(
    mut em: Emitter<N>,
    local: &Local<T>,
    start: Label,
    end: Label,
) -> Emitter<N> {
    em.visit_local_variable(&local.name, local.type_.descriptor(), start, end, local.index);
    em
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::pcode::emu::jit::gen::util::types::{SType, T_INT};
    use crate::pcode::seam_stubs::{Emitter, Label, Next};

    struct StackShape;
    impl Next for StackShape {}

    #[test]
    fn construct_local_with_int_type() {
        let local = Local::of(T_INT, "counter", 1);
        assert_eq!(local.name, "counter");
        assert_eq!(local.index, 1);
        assert_eq!(T_INT.descriptor(), "I");
    }

    #[test]
    fn construct_local_with_different_names() {
        let local1 = Local::of(T_INT, "x", 0);
        let local2 = Local::of(T_INT, "y", 1);
        assert_ne!(local1.name, local2.name);
        assert_eq!(local1.name, "x");
        assert_eq!(local2.name, "y");
    }

    #[test]
    fn declare_local_records_in_emitter() {
        let local = Local::of(T_INT, "value", 2);
        let start = Label::new();
        let end = Label::new();

        let em: Emitter<StackShape> = Emitter::new();
        let em = decl(em, &local, start, end);

        let declared = em.local_variables();
        assert_eq!(declared.len(), 1);

        let (name, descriptor, recorded_start, recorded_end, index) = &declared[0];
        assert_eq!(name, "value");
        assert_eq!(descriptor, "I");
        assert_eq!(*recorded_start, start);
        assert_eq!(*recorded_end, end);
        assert_eq!(*index, 2);
    }

    #[test]
    fn declare_multiple_locals_in_sequence() {
        let local1 = Local::of(T_INT, "x", 0);
        let local2 = Local::of(T_INT, "y", 1);
        let start = Label::new();
        let end = Label::new();

        let em: Emitter<StackShape> = Emitter::new();
        let em = decl(em, &local1, start, end);
        let em = decl(em, &local2, start, end);

        let declared = em.local_variables();
        assert_eq!(declared.len(), 2);
        assert_eq!(declared[0].0, "x");
        assert_eq!(declared[1].0, "y");
    }

    #[test]
    fn local_clone() {
        let local1 = Local::of(T_INT, "original", 5);
        let local2 = local1.clone();
        assert_eq!(local1.name, local2.name);
        assert_eq!(local1.index, local2.index);
    }
}
